@derive(PartialEq)struct S{text:String;}
@derive(PartialEq)enum E{Nada,Dato(S)}
fn Main(){
    AssertEq("é"=="é",true);
    AssertEq("é"!="é",true);
    AssertEq("é"<"🙂",true);
    AssertEq("é"<="é",true);
    AssertEq("🙂">"é",true);
    AssertEq("é">="é",true);
    AssertEq("a"<"aa",true);
    AssertEq(""<"a",true);
    AssertEq("a">"aa",false);
    var a:Array<E>=[];
    Push(edit a,E.Dato(S("é")));
    Push(edit a,E.Nada);
    var b=a;
    AssertEq(Pop(edit b),Some(E.Nada));
    AssertEq(a!=b,true);
    Push(edit b,E.Nada);
    AssertEq(a==b,true);
    let c=JoinArrays(a,b);
    AssertEq(Len(c),4);
    var n=0;
    for item in c{
        match item{E.Nada=>{},E.Dato(s)=>{n+=s.text.ByteLen();}}
    }
    AssertEq(n,4);
}

