struct S{text:String;}
enum E{Nada,Dato(S)}
fn Main(){
    var a=[S("é")];
    var b=a;
    Push(edit b,S("x"));
    AssertEq(Len(a),1);
    AssertEq(Len(b),2);
    var bytes=0;
    for r in b{bytes+=r.text.ByteLen();}
    AssertEq(bytes,3);
    var es=[E.Nada];
    Push(edit es,E.Dato(S("y")));
    let popped=Pop(edit es);
    match popped{None=>{AssertEq(false,true);},Some(v)=>{}}
    var count=0;
    for e in JoinArrays(es,es){count+=1;}
    AssertEq(count,2);
}

